// Package mslgen makes the Metal back-end's coverage functions from the
// WebGPU shader, through go-gfx/wgsl's MSL emitter, so the coverage
// arithmetic is written once in WGSL instead of once per shading language.
package mslgen

import (
	"fmt"

	"github.com/go-gfx/wgsl"
	"github.com/go-gfx/wgsl/msl"
)

// Header opens the generated file.
const Header = "// Code generated by internal/mslgen from webgpu/shader.wgsl; DO NOT EDIT.\n\n"

// Coverage is the MSL for the shader's coverage function (and cornerCenter,
// which it calls), with the Inst structure and the emitter's preamble.
func Coverage(shader string) (string, error) {
	m, err := wgsl.Parse(shader)
	if err != nil {
		return "", err
	}
	info, errs := wgsl.Check(m)
	if len(errs) > 0 {
		return "", fmt.Errorf("mslgen: the shader does not check: %v", errs)
	}
	out, err := msl.Functions(m, info, "coverage")
	if err != nil {
		return "", err
	}
	return Header + out, nil
}
